cd $PWD; python3 - <<'EOF'
f='src/server/services/invitation-service.ts'
s=open(f).read()
s=s.replace('''  const seatsUsed =''','''  const seen = new Set<string>();
  for (const invite of input.invites) {
    const email = invite.email.toLowerCase();
    if (seen.has(email)) {
      throw new Error(`${invite.email} appears more than once in this batch`);
    }
    seen.add(email);
    if (await memberRepo.findMemberByEmail(input.orgId, email)) {
      throw new Error(`${invite.email} is already a member`);
    }
    if (await invitationRepo.findPendingInvitationByEmail(input.orgId, email)) {
      throw new Error(`${invite.email} already has a pending invitation`);
    }
  }

  const seatsUsed =''')
s=s.replace('''  const existing = await memberRepo.findMember(invitation.orgId, userId);
  if (existing) return existing;

  const member = await memberRepo.insertMember(
    invitation.orgId,
    userId,
    invitation.role,
    invitation.invitedBy,
  );

  await invitationRepo.markInvitationAccepted(
    invitation.orgId,
    invitation.id,
    toIsoTimestamp(new Date()),
  );
''','''
  const user = requireFound(await userRepo.findUserById(userId), "User", userId);
  if (user.email.toLowerCase() !== invitation.email.toLowerCase()) {
    throw new Error("That invitation was sent to a different address");
  }

  const org = await orgRepo.findOrgById(invitation.orgId);
  if (!org || org.archivedAt !== null) {
    throw new Error("That organization no longer exists");
  }

  const existing = await memberRepo.findMember(invitation.orgId, userId);
  if (existing) return existing;

  const now = toIsoTimestamp(new Date());
  const former = await memberRepo.findArchivedMember(invitation.orgId, userId);
  const member = former
    ? await memberRepo.restoreMember(
        invitation.orgId,
        former.id,
        invitation.role,
        invitation.invitedBy,
        now,
      )
    : await memberRepo.insertMember(
        invitation.orgId,
        userId,
        invitation.role,
        invitation.invitedBy,
      );

  await invitationRepo.markInvitationAccepted(invitation.orgId, invitation.id, now);
''')
s=s.replace('''  const previous = requireFound(
    await invitationRepo
      .listPendingInvitations(actor.orgId)
      .then((rows) => rows.find((row) => row.id === invitationId) ?? null),
    "Invitation",
    invitationId,
  );

  await invitationRepo.revokeInvitation(actor.orgId, invitationId);

  // A re-issued link starts at the lowest invitable role; whoever resends it
  // can promote the person once they have joined.
  return inviteMember(actor, {
    orgId: actor.orgId,
    email: previous.email,
    role: "member",
  });''','''  const found = await invitationRepo.findInvitationById(actor.orgId, invitationId);
  const previous = requireFound(
    found && found.acceptedAt === null && found.revokedAt === null ? found : null,
    "Invitation",
    invitationId,
  );

  await invitationRepo.revokeInvitation(actor.orgId, invitationId);

  try {
    return await inviteMember(actor, {
      orgId: actor.orgId,
      email: previous.email,
      role: previous.role as InviteMemberInput["role"],
    });
  } catch (error) {
    await invitationRepo.restoreInvitation(actor.orgId, invitationId);
    throw error;
  }''')
s=s.replace('import * as orgRepo from "@/server/repositories/organization-repository";','import * as orgRepo from "@/server/repositories/organization-repository";\nimport * as userRepo from "@/server/repositories/user-repository";')
open(f,'w').write(s)

f='src/server/repositories/invitation-repository.ts'
s=open(f).read()
s+='''
/** Undoes a revoke; used when a re-send fails after withdrawing the old link. */
export async function restoreInvitation(
  orgId: OrgId,
  invitationId: InvitationId,
): Promise<void> {
  getDb()
    .update(invitations)
    .set({ revokedAt: null, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(orgPredicate(invitations.orgId, orgId), eq(invitations.id, invitationId)),
    )
    .run();
}
'''
open(f,'w').write(s)
EOF
